{
  "subtype": "predictive_feature_engineering",
  "focus_variable": "duration_like_resolution_value",
  "per_column": [
    {
      "name": "incident_type",
      "role": "predictor",
      "is_predictor": true,
      "rationale": "Type of incident (database, email, VPN) is a legitimate predictor of resolution time, known at intake and outside the focus variable."
    },
    {
      "name": "infrastructure_target",
      "role": "predictor",
      "is_predictor": true,
      "rationale": "The affected system/component plausibly influences how long resolution takes; independent of duration and knowable early."
    },
    {
      "name": "assigned_technician",
      "role": "predictor",
      "is_predictor": true,
      "rationale": "Individual technician can correlate with speed of resolution; a valid feature, though partly determined after assignment it is not a restatement of duration."
    },
    {
      "name": "technician_handoff",
      "role": "leakage",
      "is_predictor": false,
      "rationale": "Whether the ticket was handed off between technicians is typically only known over the course of the incident and is a consequence of prolonged handling, correlating mechanically with longer duration rather than being an independent antecedent predictor."
    },
    {
      "name": "caller_type",
      "role": "predictor",
      "is_predictor": true,
      "rationale": "Caller type (named vs ITIL user) is an intake attribute outside the focus and may carry weak-to-moderate predictive signal."
    },
    {
      "name": "issue_scope",
      "role": "predictor",
      "is_predictor": true,
      "rationale": "Scope (single user vs building-wide vs infrastructure) plausibly predicts effort/duration and is knowable at intake, independent of the outcome."
    },
    {
      "name": "severity_signal",
      "role": "predictor",
      "is_predictor": true,
      "rationale": "A boolean severity indicator is an antecedent characteristic that can influence resolution time; not a restatement of duration."
    },
    {
      "name": "issue_complexity_signal",
      "role": "leakage",
      "is_predictor": false,
      "rationale": "A generic 'complexity' label is likely inferred from or proxies the effort/time itself, making it a near-restatement of the outcome rather than an independent predictor; borderline leakage."
    }
  ],
  "n_predictors": 6,
  "predictive_utility": 0.55,
  "rationale": "Most added columns are legitimate antecedent predictors of resolution duration (incident type, infrastructure target, technician, caller type, scope, severity) that lie outside the focus and plausibly carry signal. However, technician_handoff is largely a consequence of a prolonged incident (leakage), and issue_complexity_signal reads as a proxy/restatement of the very effort that determines duration. The predictor set overlaps somewhat with existing columns (priority, category, assignment_group) and several fields are correlated with one another, limiting the marginal leverage. Net: a moderately useful but partly redundant/contaminated feature set."
}

